local WuKongClientProvider = {}

local WuKongHost = nil

function WuKongClientProvider.BuildWuKongClient(options: IWuKongOptions): IWuKongClient
	local optionsProvider = require(script.Parent.Parent.WuKongOptionsProvider)
	local defaultOptions = table.clone(optionsProvider.BuildDefaultOptions())

	if not options then
		options = {}
	end

	for k, v in options do
		defaultOptions[k] = v
	end

	if not WuKongHost then
		WuKongHost = _G.wdm.WuKong.RbxClient.WuKongClientHost(defaultOptions)
		WuKongHost:Start()
	end

	return WuKongHost
end

function WuKongClientProvider.GetWuKongClient(): IWuKongClient
	if not WuKongHost then
		error("WuKong client has not been initialized yet. Please call BuildWuKongClient first.")
	end
	return WuKongHost
end

function WuKongClientProvider.Dispose()
	WuKongHost:Dispose()
	WuKongHost = nil
end
return WuKongClientProvider
